\set ON_ERROR_STOP on
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
\ir helpers/auth.sql.inc
select no_plan();
insert into public.profiles(id,display_name,base_currency,timezone)
select id,'Synthetic reopen','USD','UTC' from auth.users where id::text like 'f0050000%';
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('f1240000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into public.budget_periods(id,profile_id,starts_on,ends_on,base_currency) values
(pg_temp.id(1),'f0050000-0000-4000-8000-000000000001','2025-01-01','2025-01-31','USD'),
(pg_temp.id(2),'f0050000-0000-4000-8000-000000000001','2025-02-01','2025-02-28','USD'),
(pg_temp.id(3),'f0050000-0000-4000-8000-000000000002','2025-01-01','2025-01-31','USD');
update public.budget_periods set status='CLOSED',closed_at='2025-03-01T00:00:00Z' where id=pg_temp.id(2);
create function pg_temp.context() returns jsonb language sql stable as $$select public.get_personal_period_close_context('2025-01-01')$$;
create function pg_temp.reopen(request uuid default pg_temp.id(20),version bigint default 1,fingerprint text default null,confirmed boolean default true)
returns jsonb language sql volatile as $$select public.reopen_personal_budget_period(request,pg_temp.id(1),version,coalesce(fingerprint,pg_temp.context()->>'reopen_hash'),confirmed)$$;
select ok((select relrowsecurity from pg_class where oid='public.budget_period_reopenings'::regclass),'Reopen evidence RLS enabled');
select ok(not has_table_privilege('authenticated','public.budget_period_reopenings',p),'No client evidence '||p) from unnest(array['INSERT','UPDATE','DELETE','TRUNCATE','TRIGGER']) p;
select ok(not has_column_privilege('authenticated','public.budget_periods',c,'UPDATE'),'No lifecycle grant '||c) from unnest(array['status','closed_at','lifecycle_version']) c;
select is(prosecdef,true,'Reopen explicitly bounded definer') from pg_proc where oid='public.reopen_personal_budget_period(uuid,uuid,bigint,text,boolean)'::regprocedure;
select ok(proconfig @> array['search_path=""'],'Reopen has empty path') from pg_proc where oid='public.reopen_personal_budget_period(uuid,uuid,bigint,text,boolean)'::regprocedure;
select ok(not has_function_privilege('anon','public.reopen_personal_budget_period(uuid,uuid,bigint,text,boolean)','EXECUTE'),'Anonymous execution denied');
set local role authenticated;
select pg_temp.set_jwt_subject('f0050000-0000-4000-8000-000000000001');
select is(current_user::text,'authenticated','Owner role');
select is(auth.uid(),'f0050000-0000-4000-8000-000000000001'::uuid,'Owner subject');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),0,repeat('a',32))$$,'40001',null,'Already open new reopen is not a successful no-op');
select public.register_income(pg_temp.id(10),pg_temp.id(1),1000,'USD','2025-01-02');
select set_config('fin124.close_hash',pg_temp.context()->>'snapshot_hash',true);
select public.close_personal_budget_period(pg_temp.id(11),pg_temp.id(1),0,current_setting('fin124.close_hash'),true);
select set_config('fin124.reopen_hash',pg_temp.context()->>'reopen_hash',true);
select set_config('fin124.summary',(select summary::text from public.budget_period_closures where id=pg_temp.id(11)),true);
select is(pg_temp.context()->>'reopen_hash',current_setting('fin124.reopen_hash'),'Closed state fingerprint deterministic');
select throws_ok($$select public.reopen_personal_budget_period(pg_temp.id(20),null,1,current_setting('fin124.reopen_hash'),true)$$,'22023',null,'Missing period rejected');
select throws_ok($$select public.reopen_personal_budget_period(pg_temp.id(20),pg_temp.id(1),1,null,true)$$,'22023',null,'Missing fingerprint rejected');
select throws_ok($$select pg_temp.reopen(null)$$,'22023',null,'Missing UUID rejected');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),null)$$,'22023',null,'Missing version rejected');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),-1)$$,'22023',null,'Negative version rejected');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),9007199254740991)$$,'22023',null,'Unsafe next version rejected');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),1,null,false)$$,'22023',null,'False confirmation rejected');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),1,null,null)$$,'22023',null,'Null confirmation rejected');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),1,'bad')$$,'22023',null,'Malformed fingerprint rejected');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),1,repeat('f',32))$$,'40001',null,'Wrong closed-state fingerprint conflicts');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),0)$$,'40001',null,'Stale lifecycle conflicts');
select is(pg_temp.reopen()->>'lifecycle_version','2','Explicit reopening advances version');
select is((select status from public.budget_periods where id=pg_temp.id(1)),'OPEN','Reopened OPEN');
select ok((select closed_at is null from public.budget_periods where id=pg_temp.id(1)),'Live close time cleared');
select is((select closure_id from public.budget_period_reopenings where id=pg_temp.id(20)),pg_temp.id(11),'Original close identity retained');
select is((select previous_closed_at from public.budget_period_reopenings where id=pg_temp.id(20)),(select closed_at from public.budget_period_closures where id=pg_temp.id(11)),'Original timestamp retained');
select is((select count(*) from public.transactions),1::bigint,'Reopening moves no money');
select is(jsonb_array_length(pg_temp.context()#>'{history,closures}'),1,'Close history remains visible while open');
select is(jsonb_array_length(pg_temp.context()#>'{history,reopenings}'),1,'Reopen history visible');
select is(pg_temp.reopen(pg_temp.id(20),1,current_setting('fin124.reopen_hash'))->>'lifecycle_version','2','Exact reopen replay on OPEN reads original result');
select throws_ok($$select pg_temp.reopen(gen_random_uuid(),1,current_setting('fin124.reopen_hash'))$$,'40001',null,'New duplicate conflicts instead of no-op');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),2,current_setting('fin124.reopen_hash'))$$,'23505',null,'Same request changed version conflicts');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),1,repeat('f',32))$$,'23505',null,'Same request changed fingerprint conflicts');
select throws_ok($$select public.reopen_personal_budget_period(pg_temp.id(20),pg_temp.id(2),1,current_setting('fin124.reopen_hash'),true)$$,'23505',null,'Same request changed period conflicts');
select public.correct_personal_transaction(pg_temp.id(21),pg_temp.id(10),0,'EDIT','{"amount_minor":2000,"transaction_date":"2025-01-02","category_id":null,"description":"Correction after reopening"}',true);
select is((select amount_minor from public.transactions where id=pg_temp.id(10)),2000::bigint,'Reopening enables ordinary bounded correction');
select is((select count(*) from public.transaction_revisions where transaction_id=pg_temp.id(10)),1::bigint,'Correction remains traceable');
select is((select summary from public.budget_period_closures where id=pg_temp.id(11)),current_setting('fin124.summary')::jsonb,'Correction never rewrites previous close summary');
select is(public.close_personal_budget_period(pg_temp.id(11),pg_temp.id(1),0,current_setting('fin124.close_hash'),true)->>'lifecycle_version','1','Old close replay reads old evidence');
select is((select status from public.budget_periods where id=pg_temp.id(1)),'OPEN','Old close replay never recloses reopened month');
select public.close_personal_budget_period(pg_temp.id(22),pg_temp.id(1),2,pg_temp.context()->>'snapshot_hash',true);
select is(pg_temp.reopen(pg_temp.id(20),1,current_setting('fin124.reopen_hash'))->>'lifecycle_version','2','Old reopen replay after another close reads original result');
select is((select status||':'||lifecycle_version from public.budget_periods where id=pg_temp.id(1)),'CLOSED:3','Old reopen cannot reopen newer close');
select throws_ok($$select pg_temp.reopen(gen_random_uuid(),1,current_setting('fin124.reopen_hash'))$$,'40001',null,'New stale reopen cannot reopen later lifecycle');
select throws_ok($$select public.register_income(gen_random_uuid(),pg_temp.id(1),1,'USD','2025-01-03')$$,'42501',null,'Closed guards apply again after reclose');
select is(jsonb_array_length(pg_temp.context()#>'{history,closures}'),2,'Every close retained after reclose');
select is(pg_temp.context()#>>'{summary,received_income_minor}','2000','Reclose captures corrected facts separately');
select is(pg_temp.reopen(pg_temp.id(23),3)->>'lifecycle_version','4','Later explicit reopen advances again');
select is(jsonb_array_length(pg_temp.context()#>'{history,reopenings}'),2,'Every reopening retained');
select is(public.close_personal_budget_period(pg_temp.id(11),pg_temp.id(1),0,current_setting('fin124.close_hash'),true)->>'lifecycle_version','1','First close replays after multiple full cycles');
select is(pg_temp.reopen(pg_temp.id(20),1,current_setting('fin124.reopen_hash'))->>'lifecycle_version','2','First reopen replays after multiple full cycles');
select is((select status||':'||lifecycle_version from public.budget_periods where id=pg_temp.id(1)),'OPEN:4','Old replay never changes latest lifecycle');
select is((select summary from public.budget_period_closures where id=pg_temp.id(11)),current_setting('fin124.summary')::jsonb,'Exact original summary survives corrections and multiple cycles');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),1,current_setting('fin124.reopen_hash'),false)$$,'22023',null,'Replay still requires explicit confirmation');
select is(public.reopen_personal_budget_period(pg_temp.id(24),pg_temp.id(2),0,public.get_personal_period_close_context('2025-02-01')->>'reopen_hash',true)->>'lifecycle_version','1','Legacy close reopens without fabricated close evidence');
select is((select closure_id from public.budget_period_reopenings where id=pg_temp.id(24)),null::uuid,'Legacy close link explicitly absent');
select is((select previous_closed_at from public.budget_period_reopenings where id=pg_temp.id(24)),'2025-03-01T00:00:00Z'::timestamptz,'Legacy original timestamp retained');
select is((select count(*) from public.budget_period_closures where budget_period_id=pg_temp.id(2)),0::bigint,'No invented legacy close');
select throws_ok($$update public.budget_periods set status='CLOSED',lifecycle_version=20 where id=pg_temp.id(1)$$,'42501',null,'Direct status/version forgery forbidden');
select throws_ok($$insert into public.budget_period_reopenings select * from public.budget_period_reopenings$$,'42501',null,'Evidence forgery forbidden');
select throws_ok($$update public.budget_period_reopenings set closed_state_hash=repeat('f',32)$$,'42501',null,'Evidence update forbidden');
select throws_ok($$delete from public.budget_period_reopenings$$,'42501',null,'Evidence delete forbidden');
reset role;
set local role authenticated;
select pg_temp.set_jwt_subject('f0050000-0000-4000-8000-000000000002');
select is(current_user::text,'authenticated','Household member role');
select is(auth.uid(),'f0050000-0000-4000-8000-000000000002'::uuid,'Household member subject');
select is((select count(*) from public.budget_period_reopenings),0::bigint,'Household member cannot read reopening evidence');
select throws_ok($$select pg_temp.reopen(pg_temp.id(20),1,current_setting('fin124.reopen_hash'))$$,'42501',null,'Household member cannot replay owner reopen');
select is(jsonb_array_length(pg_temp.context()#>'{history,reopenings}'),0,'Partner context cannot expose owner history');
reset role;
set local role authenticated;
select pg_temp.set_jwt_subject('f0050000-0000-4000-8000-000000000003');
select is(current_user::text,'authenticated','Stranger role');
select is(auth.uid(),'f0050000-0000-4000-8000-000000000003'::uuid,'Stranger subject');
select is((select count(*) from public.budget_period_reopenings),0::bigint,'Stranger cannot read reopen evidence');
select throws_ok($$select pg_temp.reopen(gen_random_uuid(),4,repeat('a',32))$$,'42501',null,'Stranger cannot reopen owner period');
select pg_temp.set_jwt_subject(null);
select is(auth.uid(),null::uuid,'Missing identity verified');
select throws_ok($$select pg_temp.reopen(gen_random_uuid(),4,repeat('a',32))$$,'42501',null,'Null identity cannot use definer');
reset role;
set local role anon;
select pg_temp.set_jwt_subject(null);
select is(current_user::text,'anon','Anonymous role');
select is(auth.uid(),null::uuid,'Anonymous identity');
select throws_ok($$select * from public.budget_period_reopenings$$,'42501',null,'Anonymous read denied');
select throws_ok($$select pg_temp.reopen(gen_random_uuid(),4,repeat('a',32))$$,'42501',null,'Anonymous reopen denied');
reset role;
select * from finish();
rollback;
